describe('Save Card Details for Future Purchases', () => {
  beforeEach(() => {
    cy.visit('/payment/card-details');
  });

  it('should successfully save a new card with valid details', () => {
    // Intercept the API call to save card details
    cy.intercept('POST', '/api/payment/save-card').as('saveCard');

    // Fill in card details form
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvc-input"]').type('123');
    cy.get('[data-testid="card-holder-name-input"]').type('John Doe');

    // Click save button
    cy.get('[data-testid="save-card-button"]').click();

    // Wait for the API call
    cy.wait('@saveCard');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Card saved successfully');

    // Verify card is added to saved cards list
    cy.get('[data-testid="saved-cards-list"]').should('contain', 'Visa ending in 1111');

    // Verify form is cleared
    cy.get('[data-testid="card-number-input"]').should('have.value', '');
  });

  it('should display error message when saving card with invalid details', () => {
    // Intercept the API call
    cy.intercept('POST', '/api/payment/save-card').as('saveCard');

    // Fill in card details with invalid data (e.g, invalid CVV)
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvc-input"]').type('12'); // Invalid CVV length
    cy.get('[data-testid="card-holder-name-input"]').type('John Doe');

    // Click save button
    cy.get('[data-testid="save-card-button"]').click();

    // Wait for the API call
    cy.wait('@saveCard');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid CVV');

    // Verify card is NOT added to saved cards list
    cy.get('[data-testid="saved-cards-list"]').should('not.contain', 'Visa ending in 1111');

    // Verify form is not cleared
    cy.get('[data-testid="card-number-input"]').should('have.value', '4111111111111111');
  });
});
